files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --accent: #f5c542;
  --font: 'Courier New', Courier, monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: var(--bg);
  background-image: repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(255,255,255,0.03) 2px, rgba(255,255,255,0.03) 4px);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--secondary);
  border-radius: 8px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 0 0 0 4px var(--bg), 0 0 0 8px var(--secondary);
}

h1 {
  font-size: 1.8rem;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 24px;
  text-shadow: 2px 2px 0 var(--secondary);
}

.mode-buttons {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.mode-btn {
  background: var(--secondary);
  color: var(--text);
  border: 2px solid var(--secondary);
  padding: 10px 16px;
  font-family: var(--font);
  font-size: 1rem;
  cursor: pointer;
  border-radius: 4px;
  transition: background 0.15s, transform 0.1s;
}

.mode-btn:hover {
  background: #1a4a7a;
}

.mode-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.mode-btn.active {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.mode-btn:active {
  transform: scale(0.97);
}

.timer {
  font-size: 5rem;
  font-weight: bold;
  color: var(--accent);
  letter-spacing: 4px;
  margin: 16px 0 24px;
  text-shadow: 3px 3px 0 var(--secondary);
  line-height: 1.1;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.control-btn {
  background: var(--secondary);
  color: var(--text);
  border: 3px solid var(--secondary);
  padding: 12px 28px;
  font-family: var(--font);
  font-size: 1.1rem;
  font-weight: bold;
  cursor: pointer;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.15s, transform 0.1s;
}

.control-btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.control-btn:hover {
  background: #1a4a7a;
}

.control-btn.primary:hover {
  background: #ff5c7a;
}

.control-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.control-btn:active {
  transform: scale(0.96);
}

.status {
  font-size: 1rem;
  color: var(--text);
  opacity: 0.8;
  min-height: 1.4em;
}

@media (max-width: 480px) {
  .timer {
    font-size: 3.5rem;
    letter-spacing: 2px;
  }
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .mode-btn, .control-btn {
    font-size: 0.95rem;
    padding: 10px 14px;
  }
}

(function () {
  const WORK_TIME = 25 * 60;
  const BREAK_TIME = 5 * 60;

  const timerDisplay = document.getElementById('timer-display');
  const startPauseBtn = document.getElementById('start-pause');
  const resetBtn = document.getElementById('reset');
  const modeWorkBtn = document.getElementById('mode-work');
  const modeBreakBtn = document.getElementById('mode-break');
  const statusText = document.getElementById('status-text');

  let mode = 'work';
  let timeLeft = WORK_TIME;
  let running = false;
  let intervalId = null;

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(timeLeft);
  }

  function setMode(newMode) {
    mode = newMode;
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    running = false;
    clearInterval(intervalId);
    intervalId = null;
    startPauseBtn.textContent = 'Start';
    modeWorkBtn.classList.toggle('active', mode === 'work');
    modeBreakBtn.classList.toggle('active', mode === 'break');
    modeWorkBtn.setAttribute('aria-pressed', mode === 'work');
    modeBreakBtn.setAttribute('aria-pressed', mode === 'break');
    statusText.textContent = mode === 'work' ? 'Work session ready' : 'Break session ready';
    updateDisplay();
  }

  function tick() {
    if (timeLeft > 0) {
      timeLeft--;
      updateDisplay();
    } else {
      clearInterval(intervalId);
      intervalId = null;
      running = false;
      startPauseBtn.textContent = 'Start';
      if (mode === 'work') {
        statusText.textContent = 'Work session complete! Take a break.';
        setMode('break');
      } else {
        statusText.textContent = 'Break complete! Ready for work.';
        setMode('work');
      }
    }
  }

  function toggleTimer() {
    if (running) {
      clearInterval(intervalId);
      intervalId = null;
      running = false;
      startPauseBtn.textContent = 'Start';
      statusText.textContent = 'Paused';
    } else {
      running = true;
      startPauseBtn.textContent = 'Pause';
      statusText.textContent = mode === 'work' ? 'Working...' : 'On break...';
      intervalId = setInterval(tick, 1000);
    }
  }

  function resetTimer() {
    clearInterval(intervalId);
    intervalId = null;
    running = false;
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    startPauseBtn.textContent = 'Start';
    statusText.textContent = mode === 'work' ? 'Work session ready' : 'Break session ready';
    updateDisplay();
  }

  startPauseBtn.addEventListener('click', toggleTimer);
  resetBtn.addEventListener('click', resetTimer);
  modeWorkBtn.addEventListener('click', function () { setMode('work'); });
  modeBreakBtn.addEventListener('click', function () { setMode('break'); });

  updateDisplay();
})();
